// A diff line's old and new line numbers as the developer sees them beside
// it: generated by the stylesheet from the line's data, outside its text,
// whether as pseudo-content or as a line-number control's digit.

import type { Locator } from "@playwright/test";

// Each listed line's shown old and new numbers, empty where it has none.
export const shownLineNumbers = (lines: Locator) =>
  lines.evaluateAll((items) =>
    items.map((item) =>
      (["old", "new"] as const).map((side) => {
        const control = item.querySelector(
          `.story-review-line-number[data-side="${side}"]`,
        );
        if (control !== null)
          return (
            /^"(\d*)"/.exec(
              getComputedStyle(control, "::before").content,
            )?.[1] ?? ""
          );
        const pseudo = side === "old" ? "::before" : "::after";
        return (
          /^"(\d*)"/.exec(getComputedStyle(item, pseudo).content)?.[1] ?? ""
        );
      }),
    ),
  );
